import{_ as n,o as e,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const o=JSON.parse('{"title":"Hukum Jaminan Kesehatan","description":"","frontmatter":{},"headers":[],"relativePath":"id/44-医疗保障法.md","filePath":"id/44-医疗保障法.md","lastUpdated":1789183869000}'),s={name:"id/44-医疗保障法.md"};function r(u,a,d,k,m,l){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="hukum-jaminan-kesehatan" tabindex="-1">Hukum Jaminan Kesehatan <a class="header-anchor" href="#hukum-jaminan-kesehatan" aria-label="Permalink to &quot;Hukum Jaminan Kesehatan&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Proyek</th><th>Konten</th></tr></thead><tbody><tr><td>Nomor dokumen</td><td>44</td></tr><tr><td>Modul</td><td>Sistem Hukum dan Kerangka Tata Kelola</td></tr><tr><td>Kata kunci utama</td><td>Hak Kesehatan, Pengobatan Simbiosis, Pengobatan Luka Kultivasi, Kesehatan Kehidupan, Sistem Asuransi Kesehatan</td></tr></tbody></table><h2 id="i-tujuan-legislasi-dan-prinsip-dasar" tabindex="-1">I. Tujuan Legislasi dan Prinsip Dasar <a class="header-anchor" href="#i-tujuan-legislasi-dan-prinsip-dasar" aria-label="Permalink to &quot;I. Tujuan Legislasi dan Prinsip Dasar&quot;">​</a></h2><p>《Hukum Jaminan Kesehatan》 adalah salah satu dari lima hukum pendukung peradaban simbiosis jangkar, bertujuan untuk menjamin hak kesehatan dan hak pengobatan semua makhluk di dalam Hengyuanzhou, membangun sistem pengobatan simbiosis yang mencakup semua ras, dan memastikan setiap makhluk dapat menerima pengobatan yang tepat waktu dan efektif saat sakit atau terluka.</p><p>Hukum ini menetapkan prinsip dasar berikut:</p><table tabindex="0"><thead><tr><th>Prinsip</th><th>Isi</th></tr></thead><tbody><tr><td>Prinsip Prioritas Kesehatan</td><td>Kesehatan kehidupan adalah dasar dari semua evolusi, negara dan peradaban menempatkan jaminan kesehatan kehidupan pada posisi prioritas</td></tr><tr><td>Prinsip Cakupan Universal</td><td>Jaminan kesehatan mencakup semua makhluk, tanpa memandang ras, tingkat kultivasi, asal-usul, dan kondisi ekonomi</td></tr><tr><td>Prinsip Diagnosis Berjenjang</td><td>Membangun sistem diagnosis tiga tingkat: perawatan primer, pengobatan regional, pengobatan tingkat lanjut, mendistribusikan sumber daya kesehatan secara rasional</td></tr><tr><td>Prinsip Kombinasi Pencegahan dan Pengobatan</td><td>Pencegahan sebagai utama, menggabungkan pencegahan dan pengobatan, menghargai pencegahan dan rehabilitasi luka kultivasi</td></tr><tr><td>Prinsip Adaptasi Antar Ras</td><td>Menyediakan rencana pengobatan yang adaptif terhadap karakteristik fisiologis ras yang berbeda, melarang penggunaan standar manusia yang seragam</td></tr><tr><td>Prinsip Sifat Kesejahteraan Umum</td><td>Layanan pengobatan dasar memiliki sifat kesejahteraan umum, tidak boleh mencabut hak pengobatan kehidupan dengan tujuan mencari keuntungan</td></tr></tbody></table><h2 id="ii-jaminan-hukum-hak-kesehatan-kehidupan" tabindex="-1">II. Jaminan Hukum Hak Kesehatan Kehidupan <a class="header-anchor" href="#ii-jaminan-hukum-hak-kesehatan-kehidupan" aria-label="Permalink to &quot;II. Jaminan Hukum Hak Kesehatan Kehidupan&quot;">​</a></h2><p>Hukum ini menetapkan dengan jelas bahwa hak kesehatan kehidupan adalah hak dasar yang diberikan kepada setiap makhluk oleh Konstitusi Simbiosis, termasuk secara spesifik:</p><ol><li><strong>Hak Pengobatan Dasar</strong>: Setiap makhluk berhak menerima layanan pengobatan dasar gratis, termasuk diagnosis dan pengobatan penyakit umum, obat-obatan dasar, pemeriksaan kesehatan rutin, dll.</li><li><strong>Hak Pengobatan Darurat</strong>: Setiap makhluk berhak menerima pengobatan darurat saat mengalami penyakit atau luka mendadak, dan lembaga pengobatan tidak boleh menolak pengobatan darurat dengan alasan apa pun.</li><li><strong>Hak Pengobatan Luka Kultivasi</strong>: Kultivator yang mengalami luka seperti gangguan energi, luka meridian, penyimpangan kultivasi, dll. selama proses kultivasi berhak menerima pengobatan profesional.</li><li><strong>Hak Persetujuan yang Diinformasikan</strong>: Pasien berhak mengetahui kondisinya sendiri, rencana pengobatan, risiko, dan prognosis, serta berhak memilih atau menolak rencana pengobatan.</li><li><strong>Hak Perlindungan Privasi</strong>: Informasi pengobatan dan data tubuh pasien dilindungi oleh hukum, tidak boleh dibocorkan atau digunakan untuk tujuan lain tanpa persetujuan pasien.</li><li><strong>Hak Jaminan Rehabilitasi</strong>: Pasien yang sakit atau terluka berhak menerima pengobatan rehabilitasi dan alat bantu, membantu mereka memulihkan kemampuan bekerja dan hidup.</li></ol><h2 id="iii-struktur-sistem-pengobatan-simbiosis" tabindex="-1">III. Struktur Sistem Pengobatan Simbiosis <a class="header-anchor" href="#iii-struktur-sistem-pengobatan-simbiosis" aria-label="Permalink to &quot;III. Struktur Sistem Pengobatan Simbiosis&quot;">​</a></h2><p>Sistem pengobatan peradaban simbiosis jangkar dibagi menjadi tiga tingkat, dengan mekanisme rujukan dan kolaborasi yang dibangun di antara tingkat-tingkat tersebut:</p><table tabindex="0"><thead><tr><th>Tingkat</th><th>Nama</th><th>Fungsi</th><th>Cakupan</th></tr></thead><tbody><tr><td>Tingkat pertama</td><td>Puskesmas Primer</td><td>Diagnosis dan pengobatan penyakit umum, pencegahan dan perawatan kesehatan, pemeriksaan dasar, transportasi darurat</td><td>Komunitas/desa/bidang kecil</td></tr><tr><td>Tingkat kedua</td><td>Pusat Pengobatan Regional</td><td>Diagnosis spesialis, pengobatan bedah, pengobatan awal luka kultivasi, rehabilitasi</td><td>Kota/wilayah/bidang menengah</td></tr><tr><td>Tingkat ketiga</td><td>Rumah Sakit Umum Pengobatan Tingkat Lanjut</td><td>Penyakit parah dan kompleks, luka kultivasi tingkat lanjut, penyakit domain kesadaran, penyakit kompleks antar ras</td><td>Inti peradaban/bidang besar</td></tr></tbody></table><p>Selain itu, &quot;Spesialisasi Luka Kultivasi&quot; didirikan: secara khusus menangani berbagai jenis luka selama proses kultivasi, termasuk kelebihan beban energi, patah meridian, invasi iblis batin, trauma jiwa, dll., dilengkapi dengan personel medis yang mahir dalam hukum kultivasi.</p><h2 id="iv-dana-jaminan-kesehatan" tabindex="-1">IV. Dana Jaminan Kesehatan <a class="header-anchor" href="#iv-dana-jaminan-kesehatan" aria-label="Permalink to &quot;IV. Dana Jaminan Kesehatan&quot;">​</a></h2><p>Dana jaminan kesehatan adalah dasar ekonomi untuk operasi sistem pengobatan simbiosis, dan sumbernya meliputi:</p><ul><li>Alokasi akumulasi publik (sumber utama)</li><li>Potongan jaminan kesehatan dalam mekanisme kontrak produksi bersama</li><li>Donasi sosial</li><li>Hasil investasi dana</li></ul><p>Cakupan pembayaran dana meliputi: biaya layanan pengobatan dasar, biaya darurat, biaya pengobatan luka kultivasi, biaya obat-obatan dasar, biaya rehabilitasi, dll. Pasien individu hanya perlu membayar biaya partisipasi kecil, dan pembebasan diberikan untuk mereka dengan kesulitan ekonomi.</p><h2 id="v-lembaga-pengobatan-dan-personel-medis" tabindex="-1">V. Lembaga Pengobatan dan Personel Medis <a class="header-anchor" href="#v-lembaga-pengobatan-dan-personel-medis" aria-label="Permalink to &quot;V. Lembaga Pengobatan dan Personel Medis&quot;">​</a></h2><ul><li><strong>Lembaga Pengobatan Publik</strong>: Didirikan oleh negara atau komunitas peradaban, bertanggung jawab atas layanan pengobatan dasar dan fungsi kesehatan masyarakat, dengan pendanaan dijamin oleh dana jaminan kesehatan.</li><li><strong>Lembaga Pengobatan Swasta</strong>: Didirikan oleh kekuatan sosial sesuai hukum, dapat menyediakan layanan pengobatan berkualitas tinggi, tetapi harus menerima pengawasan departemen kesehatan yang berwenang, dan tidak boleh menolak pasien darurat.</li><li><strong>Lembaga Pengobatan Antar Ras</strong>: Lembaga pengobatan spesialis yang didirikan untuk kebutuhan fisiologis ras khusus, dilengkapi dengan personel medis ras lain.</li><li><strong>Hak dan Kewajiban Personel Medis</strong>: Personel medis menikmati hak seperti perlindungan praktik, imbalan yang wajar, pelatihan profesional, dll., dan pada saat yang sama memiliki kewajiban untuk menyelamatkan nyawa, menghormati pasien, menjaga kerahasiaan medis, dll.</li></ul><h2 id="vi-kesehatan-masyarakat-dan-pencegahan" tabindex="-1">VI. Kesehatan Masyarakat dan Pencegahan <a class="header-anchor" href="#vi-kesehatan-masyarakat-dan-pencegahan" aria-label="Permalink to &quot;VI. Kesehatan Masyarakat dan Pencegahan&quot;">​</a></h2><p>Negara membangun sistem kesehatan masyarakat, menjalankan fungsi berikut:</p><ol><li>Pemantauan dan pencegahan serta pengendalian penyakit menular, pembentukan mekanisme peringatan epidemi antar bidang.</li><li>Pemeriksaan kesehatan universal dan manajemen catatan kesehatan.</li><li>Promosi keamanan kultivasi dan panduan pencegahan luka kultivasi.</li><li>Pengawasan kesehatan lingkungan dan keamanan makanan serta obat-obatan.</li><li>Tanggap darurat terhadap peristiwa kesehatan masyarakat mendadak.</li></ol><h2 id="vii-tanggung-jawab-hukum" tabindex="-1">VII. Tanggung Jawab Hukum <a class="header-anchor" href="#vii-tanggung-jawab-hukum" aria-label="Permalink to &quot;VII. Tanggung Jawab Hukum&quot;">​</a></h2><p>Kegiatan yang melanggar ketentuan hukum ini menanggung tanggung jawab berikut sesuai tingkat keparahan pelanggaran:</p><ul><li>Lembaga pengobatan yang menolak pasien darurat, diperintahkan memperbaiki dan didenda, dalam kasus konsekuensi parah izin praktik dicabut.</li><li>Personel medis yang menyebabkan kerusakan pasien karena kelalaian parah, menanggung tanggung jawab ganti rugi, dalam kasus parah kualifikasi praktik dicabut.</li><li>Lembaga pengobatan yang memungut biaya ilegal atau melakukan pengobatan berlebihan, diperintahkan mengembalikan biaya dan didenda.</li><li>Membocorkan privasi medis pasien, menanggung ganti rugi kerusakan moral, dalam kasus parah dituntut tanggung jawab pidana.</li><li>Memproduksi atau menjual obat palsu atau obat berkualitas rendah, keuntungan ilegal disita dan didenda, jika构成 kejahatan dituntut tanggung jawab pidana.</li></ul><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>《Hukum Jaminan Kesehatan》 adalah perwujudan dari konsep &quot;setiap orang memiliki jalan&quot; peradaban simbiosis jangkar di bidang kesehatan. Dengan membangun sistem jaminan kesehatan cakupan universal, mendirikan spesialisasi luka kultivasi, dan menjamin hak pengobatan darurat, ia memastikan setiap makhluk dapat menerima pengobatan tepat waktu saat sakit atau terluka, dan memperkuat dasar kesehatan untuk kemajuan bersama semua ras.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen terkait&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Prinsip Umum Konstitusi Simbiosis)</li><li>38-共生医疗体系 (Sistem Pengobatan Simbiosis)</li><li>45-住房保障法 (Hukum Jaminan Perumahan)</li><li>08-人人有路保障体系 (Sistem Jaminan Setiap Orang Memiliki Jalan)</li></ul>',29)])])}const p=n(s,[["render",r]]);export{o as __pageData,p as default};
